using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static partial class ForestSeatingAuthoring {
  const string GapsRequest="Logs/ForestGaps.request",GapsLogs="Logs/ForestGaps";
  sealed class GapTree {public CatalogPlacement tree;public Geometry geometry;public Vector3 position,scale,centre;public Quaternion rotation;public bool moved;}
  static Vector2 XZ(Vector3 p)=>new Vector2(p.x,p.z);
  static Vector3 Centre(GapTree t)=>WorldBounds(t.geometry,t.position,t.rotation,t.scale).center;
  static float Gap(Vector3 p,IEnumerable<GapTree> trees)=>trees.Where(t=>!t.geometry.wood).Min(t=>Vector2.Distance(XZ(p),XZ(t.centre)));
  [InitializeOnLoadMethod]static void RegisterGaps(){EditorApplication.update+=PendingGaps;}
  static void PendingGaps(){if(!File.Exists(GapsRequest)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete(GapsRequest);try{FillForestGaps();}catch(Exception e){Directory.CreateDirectory(GapsLogs);File.WriteAllText(GapsLogs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void GapOverview(Scene scene,string filename){GameObject go=null;RenderTexture rt=null;Texture2D pixels=null;var previous=RenderTexture.active;bool fog=RenderSettings.fog,async=ShaderUtil.allowAsyncCompilation;var renderers=All<DistanceVisibility>(scene).Where(v=>v.distantParts.Length>0).SelectMany(v=>v.nearParts.Concat(v.distantParts)).Distinct().ToDictionary(r=>r,r=>r.enabled);try{ShaderUtil.allowAsyncCompilation=false;foreach(var v in All<DistanceVisibility>(scene).Where(v=>v.distantParts.Length>0)){foreach(var r in v.nearParts)r.enabled=true;foreach(var r in v.distantParts)r.enabled=false;}go=new GameObject("Disposable forest coverage preview"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,scene);var camera=go.AddComponent<Camera>();camera.CopyFrom(All<CameraRig>(scene).Single().view);camera.enabled=false;camera.scene=scene;camera.cullingMask&=~(1<<10);camera.layerCullDistances=new float[32];camera.orthographic=true;camera.orthographicSize=370;camera.aspect=1;camera.transform.SetPositionAndRotation(new Vector3(0,800,0),Quaternion.Euler(90,0,0));RenderSettings.fog=false;rt=new RenderTexture(1400,1400,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;pixels=new Texture2D(1400,1400,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1400,1400),0,0);pixels.Apply();File.WriteAllBytes(GapsLogs+"/"+filename,pixels.EncodeToPNG());camera.targetTexture=null;}finally{foreach(var pair in renderers)if(pair.Key)pair.Key.enabled=pair.Value;RenderSettings.fog=fog;ShaderUtil.allowAsyncCompilation=async;RenderTexture.active=previous;if(go)UnityEngine.Object.DestroyImmediate(go);if(rt){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}if(pixels)UnityEngine.Object.DestroyImmediate(pixels);}}
  [MenuItem("Snowglow/Environment/Redistribute forest into visible gaps")]
  public static void FillForestGaps(){
   var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall with Play stopped");Directory.CreateDirectory(GapsLogs);if(!File.Exists(GapsLogs+"/Pinefall-before.unity"))Require(EditorSceneManager.SaveScene(scene,GapsLogs+"/Pinefall-before.unity",true),"backup failed");if(scene.isDirty)EditorSceneManager.SaveScene(scene,GapsLogs+"/Pinefall-unsaved-before.unity",true);cache.Clear();outerIds.Clear();slopeIds.Clear();
   var forest=All<CatalogPlacement>(scene).Where(Tree).OrderBy(p=>p.placementId).ToArray();Require(forest.Length==638||forest.Length==500,"expected saved forest population");var terrain=All<Terrain>(scene).Single();var session=All<PrototypeSession>(scene).Single();string snow=SnowData(session.Snow.seed);var originalSeed=session.Snow.seed;
   var nonforest=All<CatalogPlacement>(scene).Where(p=>!Tree(p)&&!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,FullPose);var fleet=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();var identities=forest.ToDictionary(p=>p.placementId,p=>p.assetId+"|"+p.transform.localScale.ToString("R"));var visibility=forest.ToDictionary(p=>p.placementId,p=>JsonUtility.ToJson(p.GetComponent<DistanceVisibility>()));
   var sources=All<MeshFilter>(scene).Where(f=>f.sharedMesh).Select(f=>AssetDatabase.GetAssetPath(f.sharedMesh)).Concat(All<Renderer>(scene).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(AssetDatabase.GetAssetPath)).Concat(new[]{AssetDatabase.GetAssetPath(terrain.terrainData),AssetDatabase.GetAssetPath(originalSeed)}).Where(p=>p.StartsWith("Assets/")).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));
   var mountains=All<CatalogPlacement>(scene).Where(Mountain).Select(p=>{var rs=p.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}).ToArray();var obstacles=All<Collider>(scene).Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!c.isTrigger&&!(c is TerrainCollider)&&!(c is MeshCollider&&c.GetComponentInParent<SnowField>())&&!Tree(c.GetComponentInParent<CatalogPlacement>())).Select(c=>c.bounds).ToArray();
   var trees=forest.Select(p=>new GapTree{tree=p,geometry=Data(p.assetId),position=p.transform.position,rotation=p.transform.rotation,scale=p.transform.lossyScale}).ToArray();foreach(var t in trees)t.centre=Centre(t);Validate(forest,terrain,mountains,forest.Length);GapOverview(scene,"Before.png");
   // Candidate coverage is measured at the visual tree centre, not the potentially offset placement pivot.
   var sites=new List<Vector3>();for(int z=-320;z<=320;z+=10)for(int x=-320;x<=320;x+=10){var point=new Vector3(x,Ground(terrain,new Vector3(x,0,z)),z);if(XZ(point).magnitude>322||Mathf.Abs(x)<145&&Mathf.Abs(z)<145||!VisibleGround(new Bounds(point,new Vector3(3,1,3)),mountains))continue;sites.Add(point);}
   Require(sites.Count>100,"no eligible forest ground");var originalGaps=sites.ToDictionary(p=>p,p=>Gap(p,trees));var rng=new System.Random(8110638);var plans=new List<Plan>();var rejected=new HashSet<Vector3>();var accepted=new List<Vector3>();int slopes=0,hills=0,flat=0;
   for(int move=0;move<100;move++){
    var ranked=sites.Where(p=>!rejected.Contains(p)).Select(p=>new{point=p,gap=Gap(p,trees)}).Where(s=>s.gap>23).OrderByDescending(s=>s.gap*(XZ(s.point).magnitude<295?1.15f:.85f)*(HillBand(terrain,s.point)<2?1.1f:1)).ToArray();if(ranked.Length==0)break;bool found=false;
    foreach(var site in ranked.Take(30)){
     var donors=trees.Where(t=>!LimitedWood(t.tree)&&!t.moved&&(XZ(t.centre).magnitude>=295||HillBand(terrain,t.position)==2)&&Vector2.Distance(XZ(t.centre),XZ(site.point))>45).Select(t=>new{tree=t,neighbors=trees.Count(other=>other!=t&&!other.geometry.wood&&Vector2.Distance(XZ(other.centre),XZ(t.centre))<32),nearest=trees.Where(other=>other!=t&&!other.geometry.wood).Min(other=>Vector2.Distance(XZ(other.centre),XZ(t.centre)))}).Where(d=>d.neighbors>=2&&d.nearest<24).OrderByDescending(d=>(HillBand(terrain,d.tree.position)==2?3:0)+(XZ(d.tree.centre).magnitude>=305?2:0)+d.neighbors*.12f).Select(d=>d.tree).Take(60).ToArray();
     foreach(var donor in donors){if((donor.tree.placementId??"").StartsWith(DensityPrefix)&&HillBand(terrain,site.point)==2)continue;for(int attempt=0;attempt<6;attempt++){float yaw=attempt==0?Yaw(donor.rotation):(float)rng.NextDouble()*360;var trialRotation=Rotation(donor.geometry,terrain,site.point,yaw);var offset=trialRotation*Vector3.Scale(donor.geometry.bounds.center,donor.scale);var root=site.point-new Vector3(offset.x,0,offset.z);if((donor.tree.placementId??"").StartsWith(DensityPrefix)&&HillBand(terrain,root)==2)continue;var occupied=trees.Where(t=>t!=donor).Select(t=>new Occupied{id=t.tree.placementId,point=t.position,radius=Radius(t.geometry,t.scale)}).ToList();if(!Spaced(donor.geometry,root,donor.scale,occupied)||!Fit(donor.geometry,terrain,root,yaw,donor.scale,mountains,obstacles,out var pos,out var rot))continue;var centre=WorldBounds(donor.geometry,pos,rot,donor.scale).center;float targetGap=Gap(centre,trees);if(targetGap<20||Vector2.Distance(XZ(centre),XZ(site.point))>6)continue;float donorAfter=Gap(donor.centre,trees.Where(t=>t!=donor));if(donorAfter>site.gap-3)continue;
       plans.Add(new Plan{existing=donor.tree,geometry=donor.geometry,id=donor.tree.placementId,position=pos,rotation=rot,scale=donor.scale,oldPosition=donor.position});donor.position=pos;donor.rotation=rot;donor.centre=centre;donor.moved=true;accepted.Add(site.point);int band=HillBand(terrain,pos);if(band==0)hills++;else if(band==1)slopes++;else flat++;found=true;break;
      }if(found)break;
     }if(found)break;rejected.Add(site.point);
    }if(!found)break;
   }
   Require(plans.Count>0,"no safe gap-filling relocations found");var afterGaps=sites.Select(p=>Gap(p,trees)).ToArray();float beforeMean=originalGaps.Values.Average(),afterMean=afterGaps.Average();Require(afterMean<beforeMean,"forest coverage did not improve");
   Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Fill forest gaps from dense outskirts");bool saved=false;var oldBounds=plans.SelectMany(p=>p.existing.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray();
   try{foreach(var plan in plans){Undo.RecordObject(plan.existing.transform,"Redistributed tree");plan.existing.transform.SetPositionAndRotation(plan.position,plan.rotation);PrefabUtility.RecordPrefabInstancePropertyModifications(plan.existing.transform);}Physics.SyncTransforms();Validate(forest,terrain,mountains,forest.Length);Undo.RecordObject(session.Snow,"Forest collision mask");int mask=RefreshMask(session.Snow,oldBounds,plans.SelectMany(p=>p.existing.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray());Require(snow==SnowData(session.Snow.seed),"snow quantities changed");SceneValidation.Validate(scene);MechanicsChecks.Run();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");saved=true;Undo.CollapseUndoOperations(undo);
    scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);forest=All<CatalogPlacement>(scene).Where(Tree).ToArray();terrain=All<Terrain>(scene).Single();session=All<PrototypeSession>(scene).Single();Validate(forest,terrain,mountains,forest.Length);foreach(var p in forest){Require(identities[p.placementId]==p.assetId+"|"+p.transform.localScale.ToString("R"),"variant/scale changed");var v=p.GetComponent<DistanceVisibility>();Require(v.distance==200&&v.distantDistance==2000&&v.switchBuffer==12,"visibility changed");Require(p.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled&&!c.isTrigger)==1,"solid collider policy");}foreach(var p in All<CatalogPlacement>(scene).Where(p=>nonforest.ContainsKey(p.placementId??"")))Require(nonforest[p.placementId]==FullPose(p),"nonforest pose changed");Require(fleet.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");foreach(var pair in sources)Require(pair.Value==AssetDatabase.GetAssetDependencyHash(pair.Key),"source changed "+pair.Key);Require(snow==SnowData(session.Snow.seed),"saved snow quantities changed");SceneValidation.Validate(scene);MechanicsChecks.Run();GapOverview(scene,"After.png");ForestCardsSceneReview.Run();EditorSceneManager.OpenScene(SceneValidation.ScenePath);
    File.WriteAllLines(GapsLogs+"/Relocations.csv",new[]{"id,variant,old_x,old_z,new_x,new_y,new_z"}.Concat(plans.Select(p=>p.id+","+p.geometry.asset.id+","+p.oldPosition.x+","+p.oldPosition.z+","+p.position.x+","+p.position.y+","+p.position.z)));
    File.WriteAllText(GapsLogs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Redistributed "+plans.Count+" existing trees, no additions/deletions; 638 placements and all variants/scales retained. Destinations: "+hills+" hills, "+slopes+" slopes, "+flat+" other outer-town ground; town protected. Borrowed only from locally dense outskirts/outer ring, never isolated trees or wood. Visual-centre 10m sample-grid mean nearest-tree gap "+beforeMean.ToString("F2")+" -> "+afterMean.ToString("F2")+"m across "+sites.Count+" eligible samples; mean selected gap "+accepted.Average(p=>originalGaps[p]).ToString("F2")+"m before. Full physical bounds/root 330m, terrain support/visual burial, slope rotation, mountain exclusion, LOD3, one solid box, 200m/2km card policy checked. Saved/reopened; scene validation and 19 snow checks passed. Mesh/material/Terrain/original-seed hashes, nonforest/fleet poses and snow quantities retained. Obstacle flag changes "+mask+". Native before/after overhead and four gameplay headings generated. No runtime spawning, district rebake or player-save writes. Live driving and phone costs untested.");
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  [InitializeOnLoadMethod]static void RegisterGapReview(){EditorApplication.update+=PendingGapReview;}
  static void PendingGapReview(){if(!File.Exists("Logs/ForestGapsReview.request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("Logs/ForestGapsReview.request");try{ReviewForestGapLayout();}catch(Exception e){File.WriteAllText(GapsLogs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  [MenuItem("Snowglow/Environment/Validate saved forest gap redistribution")]
  public static void ReviewForestGapLayout(){
   var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath&&!scene.isDirty&&!EditorApplication.isPlayingOrWillChangePlaymode,"open saved Pinefall stopped");cache.Clear();outerIds.Clear();slopeIds.Clear();var terrain=All<Terrain>(scene).Single();var forest=All<CatalogPlacement>(scene).Where(Tree).ToArray();var session=All<PrototypeSession>(scene).Single();Require(forest.Length==638,"current population");var before=EditorSceneManager.OpenPreviewScene(GapsLogs+"/Pinefall-before.unity");var rows=new List<string>{"id,variant,old_x,old_z,new_x,new_y,new_z"};int moved=0,hills=0,slopes=0,other=0;float oldMean=0,newMean=0;int samples=0;
   try{var originals=All<CatalogPlacement>(before).Where(Tree).ToDictionary(p=>p.placementId);Require(originals.Count==638,"baseline population");var previous=originals.Values.Select(p=>new GapTree{tree=p,geometry=Data(p.assetId),position=p.transform.position,rotation=p.transform.rotation,scale=p.transform.lossyScale}).ToArray();var current=forest.Select(p=>new GapTree{tree=p,geometry=Data(p.assetId),position=p.transform.position,rotation=p.transform.rotation,scale=p.transform.lossyScale}).ToArray();foreach(var t in previous)t.centre=Centre(t);foreach(var t in current)t.centre=Centre(t);
    var mountains=All<CatalogPlacement>(scene).Where(Mountain).Select(p=>{var rs=p.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}).ToArray();Validate(forest,terrain,mountains,forest.Length);
    foreach(var p in forest){var original=originals[p.placementId];Require(original.assetId==p.assetId&&Vector3.Distance(original.transform.localScale,p.transform.localScale)<.000001f,"local scale/variant changed "+p.placementId);var v=p.GetComponent<DistanceVisibility>();Require(v.distance==200&&v.distantDistance==2000&&v.switchBuffer==12,"visibility policy changed");Require(p.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled&&!c.isTrigger)==1,"solid collider policy");bool changed=Vector3.Distance(p.transform.position,original.transform.position)>.001f||Quaternion.Angle(p.transform.rotation,original.transform.rotation)>.01f;if(!changed)continue;Require(!Data(p.assetId).wood,"wood moved");Require(XZ(Centre(previous.Single(t=>t.tree==original))).magnitude>=295||HillBand(terrain,original.transform.position)==2,"not an outskirts/outer-ring donor");Require(!OverlapXZ(WorldBounds(Data(p.assetId),p.transform.position,p.transform.rotation,p.transform.lossyScale),new Bounds(Vector3.zero,new Vector3(270,1,270))),"tree entered town");moved++;int band=HillBand(terrain,p.transform.position);if(band==0)hills++;else if(band==1)slopes++;else other++;rows.Add(p.placementId+","+p.assetId+","+original.transform.position.x+","+original.transform.position.z+","+p.transform.position.x+","+p.transform.position.y+","+p.transform.position.z);}
    foreach(var old in All<CatalogPlacement>(before).Where(p=>!Tree(p)&&!string.IsNullOrEmpty(p.placementId))){var match=All<CatalogPlacement>(scene).Single(p=>p.placementId==old.placementId);Require(FullPose(old)==FullPose(match),"nonforest moved "+old.placementId);}var oldSession=All<PrototypeSession>(before).Single();Require(oldSession.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");Require(SnowData(oldSession.Snow.seed)==SnowData(session.Snow.seed),"snow quantities changed");
    for(int z=-320;z<=320;z+=10)for(int x=-320;x<=320;x+=10){var point=new Vector3(x,Ground(terrain,new Vector3(x,0,z)),z);if(XZ(point).magnitude>322||Mathf.Abs(x)<145&&Mathf.Abs(z)<145||!VisibleGround(new Bounds(point,new Vector3(3,1,3)),mountains))continue;oldMean+=Gap(point,previous);newMean+=Gap(point,current);samples++;}oldMean/=samples;newMean/=samples;Require(moved>0&&newMean<oldMean,"coverage did not improve");GapOverview(before,"Before.png");
   }finally{EditorSceneManager.ClosePreviewScene(before);}
   SceneValidation.Validate(scene);MechanicsChecks.Run();GapOverview(scene,"After.png");ForestCardsSceneReview.Run();EditorSceneManager.OpenScene(SceneValidation.ScenePath);File.WriteAllLines(GapsLogs+"/Relocations.csv",rows);File.WriteAllText(GapsLogs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Saved/reopened redistribution: "+moved+" existing trees moved from outskirts/outer ring into gaps; no additions/deletions. 638 placements, exact variants and unchanged local scales. Destinations: "+hills+" hills, "+slopes+" slopes, "+other+" other eligible outer-town ground. No wood or nonforest/fleet movement; town kept clear. Mean visual-centre nearest-tree gap on "+samples+" eligible 10m samples: "+oldMean.ToString("F2")+" -> "+newMean.ToString("F2")+"m. Full forest seating, visual burial, slope rotation, 330m full-bound/root cap, mountain exclusion, LOD3 and one solid box checked. 200m switching / 12m buffer / 2km cards retained. Scene validation and 19 snow checks passed, snow quantities unchanged. Native before/after overheads and four gameplay headings rendered. No runtime spawning, district rebake or player-save writes. Phone performance and live driving untested.");
  }

 }
